class Codec:
    def encode(self, strs: List[str]) -> str:
        encoded_parts = []
        for s in strs:
            encoded_parts.append(f"{len(s)}#{s}")
        return "".join(encoded_parts)

    def decode(self, s: str) -> List[str]:
        result = []
        i = 0
        n = len(s)
        while i < n:
            delim_pos = s.find('#', i)
            length = int(s[i:delim_pos])
            start = delim_pos + 1
            end = start + length
            result.append(s[start:end])
            i = end
        return result

    def __new__(cls, strs=None):
        inst = super().__new__(cls)
        if strs is not None and isinstance(strs, list):
            return inst.decode(inst.encode(strs))
        return inst

