        """Encodes a list of strings to a single string."""
        encoded_parts = []
        for s in strs:
            encoded_parts.append(f"{len(s)}#{s}")
        return "".join(encoded_parts)

    def decode(self, s: str) -> List[str]:
        """Decodes a single string to a list of strings."""
        decoded_strs = []
        index = 0
        n = len(s)

        while index < n:
            delimiter_pos = s.find("#", index)
            length = int(s[index:delimiter_pos])
            start_pos = delimiter_pos + 1
            decoded_strs.append(s[start_pos : start_pos + length])
            index = start_pos + length

        return decoded_strs

